### 3. `packages/core/agent-loop/tests/tool-calls.spec.ts`

新增 `schema-aware argument parsing` 测试组，共 9 个用例：

```ts
describe('tool-call scheduler: schema-aware argument parsing', () => {
  /** A tool that records the parsed arguments it receives. */
  function parsingTool() {
    const received: unknown[] = []
    const tool = defineContentToolFixture({
      name: 'parse',
      description: 'parsing probe',
      parameters: {
        tenantId: { type: 'string' },
        count: { type: 'number' },
        bigId: { type: 'integer' },
        tags: { type: 'array', items: { type: 'string' } },
        loose: { type: 'array' },
        meta: { type: 'object', properties: { note: { type: 'string' } }, additionalProperties: false },
        open: { type: 'object', additionalProperties: false },
      },
      async execute(args) {
        received.push(args)
        return [{ type: 'text', text: 'ok' }]
      },
    })
    return { tool, received }
  }

  it('preserves overflowing integers verbatim and coerces numbers to declared string fields', async () => {
    const { probe } = await run('{"tenantId":9876543210987654321,"count":3,"bigId":42,"tags":[123,456],"loose":[7],"meta":{"note":789},"open":{},"extra":5}')
    expect(probe.received).toEqual([{
      tenantId: '9876543210987654321',
      count: 3,
      bigId: 42,
      tags: ['123', '456'],
      loose: [7],
      meta: { note: '789' },
      open: {},
      extra: 5,
    }])
  })

  it('coerces safe numbers for string fields and keeps the largest safe integer numeric', async () => {
    const { probe } = await run('{"tenantId":123,"count":9007199254740991}')
    expect(probe.received).toEqual([{ tenantId: '123', count: 9007199254740991 }])
  })

  it('quotes the smallest unsafe 16-digit integer for a string field', async () => {
    const { probe } = await run('{"tenantId":9007199254740992,"count":9007199254740991}')
    expect(probe.received).toEqual([{ tenantId: '9007199254740992', count: 9007199254740991 }])
  })

  it('preserves a negative overflowing integer for a string field', async () => {
    const { probe } = await run('{"tenantId":-9876543210987654321}')
    expect(probe.received).toEqual([{ tenantId: '-9876543210987654321' }])
  })

  it('quotes an overflowing integer even for an integer field, failing validation instead of rounding', async () => {
    const { agent, probe } = await run('{"bigId":12345678901234567890}')
    expect(probe.received).toEqual([])
    const result = events(agent).find(e => e.type === 'tool/result')
    expect(result!.data.error).toMatchObject({ code: 'INVALID_ARGS' })
  })

  it('preserves invalid JSON as text, failing validation instead of dispatching', async () => {
    const { agent, probe } = await run('{not json')
    expect(probe.received).toEqual([])
    const result = events(agent).find(e => e.type === 'tool/result')
    expect(result!.data.error).toMatchObject({ code: 'INVALID_ARGS' })
  })

  it('leaves null values untouched during schema coercion', async () => {
    const { agent, probe } = await run('{"meta":null}')
    expect(probe.received).toEqual([])
    const result = events(agent).find(e => e.type === 'tool/result')
    expect(result!.data.error).toMatchObject({ code: 'INVALID_ARGS' })
  })

  it('maps empty arguments to an empty object and leaves token-free JSON untouched', async () => {
    const empty = await run('')
    expect(empty.probe.received).toEqual([{}])
    const bare = await run('{}')
    expect(bare.probe.received).toEqual([{}])
  })

  it('passes arguments through unchanged for an unregistered tool', async () => {
    const { agent } = await run('{"tenantId":123}', 'ghost')
    const result = events(agent).find(e => e.type === 'tool/result')
    expect(result!.data.error).toMatchObject({ code: 'UNKNOWN_TOOL' })
  })
})
```

